import React from "react";
import { Link } from "react-router-dom";

const Navbar = () => {
  return (
    <div className="navbar">
      {/* <h3>Navbar</h3> */}
      <Link to={"/users"}>users</Link>
      <Link to={"/register"}>register</Link>
      <Link to={"/login"}>login</Link>
    </div>
  );
};

export default Navbar;
